const P = $('Plan langs').all().map(i => i.json);
const out = []; for (const p of P) for (const pg of [1,2,3]) out.push({ json: { tag: p.tag, pid: p.pid, url: 'https://api.lokalise.com/api2/projects/' + p.pid + '/keys?limit=5000&page=' + pg + '&disable_references=1' } });
return out;

const EXC = ['pst','ps','cus','pt_old'];
const P = $('Plan langs').all().map(i => i.json); const LR = $('Fetch langs').all().map(i => i.json);
const langs = {}; P.forEach((p, i) => { const arr = LR[i].languages; if (!Array.isArray(arr)) throw new Error('no languages for ' + p.tag + ': ' + JSON.stringify(LR[i]).slice(0,300)); langs[p.tag] = arr.filter(l => !EXC.includes(l.lang_iso)).map(l => [l.lang_iso, l.lang_id]); });
const req = $('Plan lite').all().map(i => i.json); const res = $input.all().map(i => i.json);
const ids = { mono: [], pdf: [] };
res.forEach((b, i) => { if (!Array.isArray(b.keys)) throw new Error('no keys array ' + req[i].url + ' ' + JSON.stringify(b).slice(0,300)); ids[req[i].tag].push(...b.keys.map(k => k.key_id)); });
const out = [];
for (const p of P) { const u = [...new Set(ids[p.tag])]; const lid = langs[p.tag].map(x => x[1]).join(',');
  for (let i = 0; i < u.length; i += 100) out.push({ json: { tag: p.tag, url: 'https://api.lokalise.com/api2/projects/' + p.pid + '/keys?limit=100&include_translations=1&disable_references=1&filter_translation_lang_ids=' + lid + '&filter_key_ids=' + u.slice(i, i+100).join(',') } }); }
out[0].json.langs = langs; out[0].json.counts = { mono: new Set(ids.mono).size, pdf: new Set(ids.pdf).size };
return out;

const req = $('Plan full').all().map(i => i.json); const res = $input.all().map(i => i.json);
const LING = ['daniel@dgmultilingualservices.com','qrcodelocalization@gmail.com','47natcha@gmail.com','therese.svardsten@gmail.com','mteres@terestraducciones.com','sara.guinot.trad@gmail.com','arandatrad@gmail.com','sabrathan@gmail.com','farahputri@gmail.com','dmluciahorea@gmail.com','roxanamoldovan25@gmail.com','root-translations@outlook.com','austra.muizniece@gmail.com','harald.roald@gmail.com','ellen.de.venter@outlook.com','ilaria.roncaglia@gmail.com','silke.luehrmann@gmx.de','boh.vozniuk@gmail.com','vidiasc@gmail.com','ivanaturcin@ymail.com','julius.valkiunas@gmail.com','jaromirvicari@me.com','karahansisman@gmail.com','katri.varvikko@gmail.com','kenneth@phraseit.dk','translation@cornell.hu','ruckova.lucia@gmail.com','marit.teichmann@gmail.com','michal.tosza@translators.org.pl','mteixeira@sacradomus.com','bruno@bsttranslations.com','nerissaneptuno@gmail.com','straus.translations@gmail.com','quentinnguyen.localize@gmail.com','futuremedia@sdl.com','silis.martins@gmail.com'];
const nm = k => typeof k.key_name === 'object' ? (k.key_name.web || k.key_name.other || k.key_name.ios || k.key_name.android) : k.key_name;
const S = t => typeof t.translation === 'object' ? JSON.stringify(t.translation) : (t.translation || '');
const norm = s => String(s || '').replace(/\s+/g, ' ').trim();
const mono = [], pdf = [];
res.forEach((b, i) => { if (!Array.isArray(b.keys)) throw new Error('no keys'); (req[i].tag === 'mono' ? mono : pdf).push(...b.keys); });
const mByName = {}, mByEn = {};
for (const k of mono) { const tr = {}; let en = ''; for (const t of k.translations || []) { tr[t.language_iso] = { v: S(t), by: t.modified_by_email, tid: t.translation_id }; if (t.language_iso === 'en') en = norm(S(t)); } const rec = { kid: k.key_id, k: nm(k), en, tr }; mByName[nm(k)] = rec; if (en) (mByEn[en] = mByEn[en] || []).push(rec); }
const byWho = {}, byWhoMono = {}; let pdfStrings = 0;
const cat = { match: 0, differs: 0, monoLingDiff: 0, noMonoKey: 0, enChangedSameName: 0, matchedByEnOnly: 0 };
const samples = { noMonoKey: [], enChangedSameName: [], differs: [], monoLingDiff: [] };
const lingPdfByLang = {};
for (const k of mono) for (const t of k.translations || []) { if (t.language_iso === 'en') continue; byWhoMono[t.modified_by_email] = (byWhoMono[t.modified_by_email] || 0) + 1; }
for (const k of pdf) { let en = ''; const tr = {}; for (const t of k.translations || []) { tr[t.language_iso] = { v: S(t), by: t.modified_by_email }; if (t.language_iso === 'en') en = norm(S(t)); }
  for (const [iso, p] of Object.entries(tr)) { if (iso === 'en' || !p.v) continue; pdfStrings++; byWho[p.by] = (byWho[p.by] || 0) + 1; if (!LING.includes(p.by)) continue;
    lingPdfByLang[iso] = (lingPdfByLang[iso] || 0) + 1;
    const same = mByName[nm(k)]; let target = null; let how = '';
    if (same && same.en === en) { target = same; how = 'name'; } else if (same && same.en !== en) { cat.enChangedSameName++; if (samples.enChangedSameName.length < 15) samples.enChangedSameName.push({ k: nm(k), iso, pdfEn: en, monoEn: same.en, pdf: p.v, mono: (same.tr[iso] || {}).v, by: p.by }); continue; }
    else if (mByEn[en]) { target = mByEn[en][0]; how = 'en'; cat.matchedByEnOnly++; }
    else { cat.noMonoKey++; if (samples.noMonoKey.length < 10) samples.noMonoKey.push({ k: nm(k), iso, en, by: p.by }); continue; }
    const m = target.tr[iso] || { v: '' };
    if (m.v === p.v) { cat.match++; continue; }
    if (LING.includes(m.by)) { cat.monoLingDiff++; if (samples.monoLingDiff.length < 10) samples.monoLingDiff.push({ k: target.k, iso, pdf: p.v, pdfBy: p.by, mono: m.v, monoBy: m.by }); continue; }
    cat.differs++; if (samples.differs.length < 20) samples.differs.push({ k: target.k, how, iso, pdf: p.v, pdfBy: p.by, mono: m.v, monoBy: m.by }); } }
return [{ json: { pdfKeys: pdf.length, monoKeys: mono.length, pdfStrings, lingPdfStrings: Object.values(lingPdfByLang).reduce((a,b)=>a+b,0), lingPdfByLang, cat, byWho, byWhoMono, samples } }];
